235	/** Decrypt + return the account's SFTP password (owner or admin). cPanel-style. */
236	export async function revealHostingSftpPassword(accountId: string): Promise<{ password?: string; error?: string }> {
237	  const user = await requireUser();
238	  // An impersonating admin must not exfiltrate a customer's live SFTP credential
239	  // (matches orderHostingAccount/createHostingDatabase — audit LOW-1).
240	  await assertNotImpersonating();
241	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true, sftpPasswordEnc: true } });
242	  if (!a) return { error: "Not found." };
243	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
244	  const pw = a.sftpPasswordEnc ? decryptSecret(a.sftpPasswordEnc) : null;
245	  if (!pw) return { error: "No password on record yet — the account is still being set up." };
246	  return { password: pw };
