346	/**
347	 * Install the per-account Adminer database manager (or return the existing one).
348	 * Owner-or-admin + not-impersonating (same discipline as every resource-creating
349	 * action). Queues an INSTALL_DBTOOL task that drops Adminer into THIS account's
350	 * webroot at a randomized path served by the account's own FPM socket. The
351	 * customer logs in with their own SCOPED DB user, so a leaked path grants no
352	 * cross-tenant access (see the worker handler's SECURITY note). Idempotent: if the
353	 * tool is already installed, returns its path without re-queuing.
354	 */
355	export async function installDbTool(accountId: string): Promise<{ ok?: boolean; error?: string; url?: string }> {
356	  const user = await requireUser();
357	  await assertNotImpersonating();
358	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, dbToolPath: true } });
359	  if (!a) return { error: "Account not found." };
360	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
361	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
362	  if (a.dbToolPath) return { ok: true, url: a.dbToolPath };
363	  // Don't queue a second install while one is already in flight.
364	  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "INSTALL_DBTOOL", status: { in: ["PENDING", "RUNNING"] } } });
365	  if (inFlight) return { ok: true };
366	  const token = randomBytes(16).toString("hex").slice(0, 32); // 32 lowercase hex chars
367	  if (!isValidDbToolToken(token)) return { error: "Couldn’t start the install — try again." };
368	  const path = `/nxtools-${token}/adminer.php`;
369	  await db.hostingTask.create({ data: { accountId, kind: "INSTALL_DBTOOL", payload: JSON.stringify({ token, path }) } });
370	  revalidatePath(`/dashboard/hosting/${accountId}`);
371	  return { ok: true };
372	}
