484	  const cur = a.plan;
485	  const all = await db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
486	  const plans = all
487	    .filter((p) => p.id !== cur.id && p.priceCents >= cur.priceCents && p.diskGB >= cur.diskGB && (p.priceCents > cur.priceCents || p.diskGB > cur.diskGB))
488	    .map((p) => ({
