496	/**
497	 * Move a hosting account UP to a larger plan. Same purchase discipline as
498	 * orderHostingAccount: no spending while impersonating, wallet charge in the same
499	 * tx that mutates the account.
500	 *
501	 * Billing choice (kept simple + honest): we charge the FULL per-term price
502	 * DIFFERENCE (new − current) now, and leave the renewal date unchanged; future
503	 * terms bill at the new plan price. No mid-term proration or refunds — that keeps
504	 * the flow one debit and never owes the customer money back. The customer sees the
505	 * exact delta before confirming. Only UP is allowed (a downgrade would need a
506	 * refund path we don't have).
507	 */
508	export async function upgradeHostingPlan(accountId: string, newPlanId: string): Promise<HostingResult> {
509	  const user = await requireUser();
510	  await assertNotImpersonating();
511	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
512	  if (!a) return { error: "Account not found." };
513	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
514	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
515	  const newPlan = await db.hostingPlan.findUnique({ where: { id: newPlanId } });
516	  if (!newPlan || !newPlan.active) return { error: "That plan isn’t available." };
517	  if (newPlan.id === a.planId) return { error: "You’re already on this plan." };
518	  const cur = a.plan;
519	  // Up-only guard (re-checked server-side; never trust the client's picker).
520	  if (newPlan.priceCents < cur.priceCents || newPlan.diskGB < cur.diskGB) {
521	    return { error: "You can only move to a larger plan." };
522	  }
523	  const limits = planLimits(newPlan);
524	  const chargeCents = Math.max(0, newPlan.priceCents - cur.priceCents);
525	  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };
526	
527	  try {
528	    await db.$transaction(async (tx) => {
529	      if (chargeCents > 0) {
530	        await debitWallet(tx, user.id, chargeCents);
531	        await tx.walletTransaction.create({
532	          data: { userId: user.id, amountCents: -chargeCents, description: `Web Hosting upgrade: ${cur.name} → ${newPlan.name} for ${a.primaryDomain}` },
533	        });
534	      }
535	      // Snapshot the new plan's limits onto the account (same as orderHostingAccount
536	      // does at creation), so a later plan edit can't silently re-quota this account.
537	      // phpVersion is left as-is: an upgrade only widens the allowed set.
538	      await tx.hostingAccount.update({
539	        where: { id: a.id },
540	        data: { planId: newPlan.id, diskQuotaMB: limits.diskGB * 1024, maxSites: limits.maxSites, maxDatabases: limits.maxDatabases },
541	      });
542	      // Enact the node-level change (raise disk quota + rewrite FPM pool).
543	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "APPLY_PLAN_LIMITS" } });
544	    });
545	  } catch (e) {
546	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
547	    return { error: "Couldn’t upgrade the plan. Your wallet was not charged — try again." };
548	  }
549	
550	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.upgrade", detail: `${cur.name} → ${newPlan.name} · ${a.primaryDomain}` } }).catch(() => {});
551	  revalidatePath(`/dashboard/hosting/${accountId}`);
552	  return { ok: true };
553	}
