119	 * The name-based nginx vhost for one account. It ALWAYS emits a `listen 443 ssl`
120	 * server block so nginx answers HTTPS from the moment the account exists —
121	 * `ssl.certDir` is the real Let's Encrypt live dir when `ssl.real` is true, else
122	 * the per-account SELF-SIGNED fallback generated at provision time. That is the
123	 * whole "clean setup always" guarantee: HTTPS shows a cert WARNING, never
124	 * ERR_CONNECTION_REFUSED. The HTTP→HTTPS redirect fires ONLY once a real cert
125	 * exists; a self-signed site still serves its body over both 80 and 443 (so it
126	 * can't 301-loop a visitor into an untrusted-cert dead end). Shared IP; routed
127	 * purely by server_name; PHP proxied to THIS account's socket only, root jailed to
128	 * its webroot. Pure string — no interpolation reaches a shell here.
129	 */
130	function renderHostingVhost(username: string, domain: string, webroot: string, sock: string, ssl: { certDir: string; real: boolean }): string {
131	  const phpLoc = [
132	    `    location ~ \\.php$ {`,
133	    `        include fastcgi_params;`,
134	    `        fastcgi_pass unix:${sock};`,
135	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
136	    `    }`,
137	  ].join("\n");
138	  const body = [
139	    `    root ${webroot};`,
140	    // Refuse to follow a symlink whose target isn't owned by the same user as the
141	    // link — blocks a tenant symlinking to a victim's wp-config.php that nginx
142	    // (www-data) would otherwise happily serve (cross-tenant read, audit CRITICAL-1).
143	    `    disable_symlinks if_not_owner;`,
144	    `    index index.php index.html;`,
145	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
146	    phpLoc,
147	    `    location ~ /\\. { deny all; }`,
148	  ].join("\n");
149	  const http = [
150	    `server {`,
151	    `    listen 80;`,
152	    `    listen [::]:80;`,
153	    `    server_name ${domain} www.${domain};`,
154	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
155	    // Redirect to HTTPS only with a REAL cert; a self-signed site serves over 80 too.
156	    ssl.real ? `    location / { return 301 https://$host$request_uri; }` : body,
157	    `}`,
158	  ].join("\n");
159	  const https = [
160	    `server {`,
161	    `    listen 443 ssl;`,
162	    `    listen [::]:443 ssl;`,
163	    `    server_name ${domain} www.${domain};`,
164	    `    ssl_certificate ${ssl.certDir}/fullchain.pem;`,
165	    `    ssl_certificate_key ${ssl.certDir}/privkey.pem;`,
166	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
167	    body,
168	    `}`,
169	  ].join("\n");
170	  return `${http}\n${https}\n`;
171	}
