1216	  await db.hostingTask.update({ where: { id: task.id }, data: { status: "RUNNING" } });
1217	  const a = task.account;
1218	  // Lifecycle tasks deliberately run on a NON-active account: the admin action
1219	  // flips status to SUSPENDED / DELETING *before* queuing, so gating them on ACTIVE
1220	  // (like the content tasks) would make suspend/terminate silent no-ops — the kill
1221	  // switch must still fire. Content tasks (PHP/WP/backup/restore) stay ACTIVE-only.
1222	  const isLifecycle = task.kind === "SUSPEND" || task.kind === "UNSUSPEND" || task.kind === "TERMINATE";
1223	  if (!isLifecycle && a.status !== "ACTIVE") { await failTask(task.id, "the account is not active"); return; }
1224	  try {
1225	    const conn = await connectNode(a.node);
1226	    try {
1227	      let result: string | null = null;
1228	      if (task.kind === "PHP_SWITCH") await taskPhpSwitch(conn, a, task.payload);
1229	      else if (task.kind === "WORDPRESS_INSTALL") result = await taskWordpressInstall(conn, a, task.payload);
1230	      else if (task.kind === "APP_INSTALL") result = await taskAppInstall(conn, a, task.payload);
1231	      else if (task.kind === "BACKUP") await taskBackup(conn, a, task.id);
1232	      else if (task.kind === "RESTORE") await taskRestore(conn, a, task.payload);
1233	      else if (task.kind === "SUSPEND") await taskSuspend(conn, a);
1234	      else if (task.kind === "UNSUSPEND") await taskUnsuspend(conn, a);
1235	      else if (task.kind === "TERMINATE") await taskTerminate(conn, a);
1236	      else if (task.kind === "CREATE_SUBDOMAIN") await taskCreateSubdomain(conn, a, task.payload);
1237	      else if (task.kind === "DELETE_SUBDOMAIN") await taskDeleteSubdomain(conn, a, task.payload);
1238	      else if (task.kind === "CREATE_ADDON_DOMAIN") await taskCreateAddonDomain(conn, a, task.payload);
