63	export async function fsList(t: HostingFsTarget, relPath: string): Promise<FsEntry[]> {
64	  const p = safeRel(relPath);
65	  return withSftp(t, (sftp) => new Promise<FsEntry[]>((resolve, reject) => {
66	    sftp.readdir(p, (err, list) => {
67	      if (err) return reject(err);
68	      resolve(
69	        list
70	          .map((e) => ({ name: e.filename, isDir: (e.attrs.mode & 0o40000) !== 0, size: e.attrs.size, modified: (e.attrs.mtime ?? 0) * 1000 }))
71	          .filter((e) => e.name !== "." && e.name !== "..")
72	          .sort((a, b) => Number(b.isDir) - Number(a.isDir) || a.name.localeCompare(b.name)),
73	      );
74	    });
75	  }));
76	}
