113	export async function fsWriteBuffer(t: HostingFsTarget, relPath: string, buf: Buffer): Promise<void> {
114	  const p = safeRel(relPath);
115	  await withSftp(t, (sftp) => new Promise<void>((resolve, reject) => {
116	    const stream = sftp.createWriteStream(p);
117	    stream.on("close", () => resolve());
118	    stream.on("error", reject);
119	    stream.end(buf);
120	  }));
121	}
