243	/**
244	 * DNS→HTTPS stepper driven by the REAL serve-verification the worker records
245	 * (serveHttpOk / serveHttpsOk / sslActive), so it can never claim "live" while
246	 * HTTPS actually refuses. Three overall states, per the account's measured health:
247	 *   • verified — a trusted cert is live (sslActive) and 443 answers → "HTTPS live ✓"
248	 *   • issuing  — the site answers (self-signed 443 or HTTP) but no trusted cert yet
249	 *   • dns      — nothing answers for the domain yet (DNS not pointed at us)
250	 */
251	function DnsStepper({ account }: { account: HostingAccountView }) {
252	  const checked = account.healthCheckedAt != null || account.serveHttpOk != null;
253	  const serving = account.serveHttpOk === true || account.serveHttpsOk === true;
254	  const verified = account.sslActive && account.serveHttpsOk !== false;
255	  const state: "verified" | "issuing" | "dns" | "pending" =
256	    verified ? "verified" : serving ? "issuing" : checked ? "dns" : "pending";
257	
258	  const steps = [
259	    { label: "Point domain", done: true, hint: "Add the A record above" },
260	    {
261	      label: "Site live",
262	      done: state === "issuing" || state === "verified",
263	      hint: state === "issuing" || state === "verified" ? "Serving traffic" : state === "dns" ? "DNS not detected yet" : "Checking…",
264	    },
265	    {
266	      label: "HTTPS verified",
267	      done: state === "verified",
268	      hint: state === "verified" ? "Certificate trusted" : state === "issuing" ? "Issuing certificate" : "Auto after DNS",
269	    },
270	  ];
271	
272	  const headline =
273	    account.healthNote ??
274	    (state === "verified" ? "HTTPS live — verified" : state === "issuing" ? "HTTP live, HTTPS issuing" : state === "dns" ? "DNS not detected yet" : "Not checked yet");
275	  const headlineTone = state === "verified" ? "text-emerald-300" : state === "dns" ? "text-slate-400" : "text-amber-300";
276	
277	  return (
278	    <div className="mt-4">
279	      <div className="flex items-center">
280	        {steps.map((s, i) => (
281	          <div key={s.label} className="flex flex-1 items-center last:flex-none">
282	            <div className="flex flex-col items-center">
283	              <span className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] ${s.done ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300" : "border-amber-500/40 bg-amber-500/10 text-amber-300"}`}>
284	                {s.done ? "✓" : i + 1}
285	              </span>
286	            </div>
287	            {i < steps.length - 1 && <div className={`mx-2 h-px flex-1 ${steps[i + 1].done ? "bg-emerald-500/40" : "bg-white/10"}`} />}
288	          </div>
289	        ))}
290	      </div>
291	      <div className="mt-1.5 flex items-start justify-between text-[11px]">
292	        {steps.map((s) => (
293	          <div key={s.label} className="flex-1 text-center first:text-left last:text-right">
294	            <p className={s.done ? "text-emerald-300" : "text-slate-400"}>{s.label}</p>
295	            <p className="text-slate-500">{s.hint}</p>
296	          </div>
297	        ))}
298	      </div>
299	      <p className={`mt-3 text-xs font-medium ${headlineTone}`}>
300	        {headline}
301	        {account.healthCheckedAt && (
302	          <span className="ml-1 font-normal text-slate-500">· checked {new Date(account.healthCheckedAt).toLocaleTimeString()}</span>
303	        )}
304	      </p>
305	      {state !== "verified" && (
306	        <p className="mt-1 text-xs text-slate-500">
307	          A trusted HTTPS certificate is issued automatically once your domain resolves to us — this can take a few minutes after you set the DNS record. Use <span className="text-slate-300">Go live</span> to check right away.
308	        </p>
309	      )}
310	    </div>
311	  );
312	}
