// Proprietary in-portal DB manager — query transport to a hosting node's MySQL.
//
// SECURITY MODEL (read before touching this file):
//
//   * ISOLATION IS THE MYSQL GRANT, NOT AN APP CHECK. Every query runs
//     authenticated as the account's SCOPED manager user (`<username>_mgr`),
//     which is granted on `<username>\_%`.* ONLY (see buildDbMgrGrantSql). MySQL
//     itself refuses that user any access to another tenant's databases, to the
//     `mysql`/`sys`/`performance_schema` system schemas, and — being a db-scoped
//     grant — to FILE/PROCESS/SUPER (so no LOAD_FILE / INTO OUTFILE file reads).
//     `information_schema` stays readable but MySQL filters its rows to objects
//     the connecting user can see, i.e. this account's own databases. The app
//     ALSO validates the target db belongs to the account (defence in depth), but
//     even a bug there cannot breach the grant.
//
//   * WHY WE SSH AS ROOT. The account's own OS user is `ForceCommand
//     internal-sftp` (SFTP-only — it cannot exec a shell), so we reach the node's
//     `mysql` client over the platform's existing root SSH (same credential the
//     provisioner uses). Root on the box is NOT root in MySQL here: we pass
//     `--user=<mgr>` so the *MySQL* session is the scoped, grant-confined user.
//
//   * SQL IS NEVER INTERPOLATED INTO A SHELL. The customer's SQL is written to
//     the `mysql` process STDIN over the SSH channel — it never appears on the
//     command line, so there is no shell-injection surface. The command line
//     carries only OUR generated, charset-validated identifiers (db name, mgr
//     user) and the mgr password via `MYSQL_PWD` (kept off argv). The whole run
//     is wrapped in `timeout` on the node AND a JS-side channel timeout, and the
//     output is byte-capped, so a runaway/huge query can't hang or OOM us.
//
// This module is plain (non-"use server") + synchronous-friendly so the server
// actions in lib/actions-hosting-db.ts can call it directly, exactly like
// lib/hosting-fs.ts does for the file manager.

import { Client } from "ssh2";
import { decryptSecret } from "./crypto-box";
import { isValidDbIdentifier } from "./hosting";

export type DbNodeTarget = {
  sshHost: string;
  sshPort: number;
  rootPassword: string;
  mgrUser: string;
  mgrPassword: string;
};

/** Build the transport target for an account: the node's root SSH credential (to
 *  reach the `mysql` client) plus the account's scoped manager MySQL credential
 *  (what the mysql session actually authenticates as). Returns null until the
 *  manager user has been provisioned on the node. Lives in this plain module (not
 *  the "use server" actions file) because it is synchronous. */
export function dbTargetFor(a: {
  node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null };
  dbMgrUser: string | null;
  dbMgrPassEnc: string | null;
}): DbNodeTarget | null {
  const rootPassword = a.node.rootPasswordEnc ? decryptSecret(a.node.rootPasswordEnc) : null;
  const mgrPassword = a.dbMgrPassEnc ? decryptSecret(a.dbMgrPassEnc) : null;
  if (!rootPassword || !a.dbMgrUser || !mgrPassword) return null;
  return { sshHost: a.node.sshHost, sshPort: a.node.sshPort, rootPassword, mgrUser: a.dbMgrUser, mgrPassword };
}

const CONNECT_TIMEOUT_MS = 20_000;
/** Hard ceiling on a single query, enforced on BOTH ends: `timeout` on the node
 *  kills the mysql process, and the JS timer tears down the SSH channel. */
const QUERY_TIMEOUT_S = 15;
const QUERY_TIMEOUT_MS = (QUERY_TIMEOUT_S + 5) * 1000;
/** Cap the raw bytes we buffer from a result so a `SELECT * FROM huge` can't OOM
 *  the app node — we stop reading and mark the result truncated. */
const MAX_OUTPUT_BYTES = 2 * 1024 * 1024; // 2 MiB
/** Cap on the SQL we will ship to the node (a sane upper bound; the UI edits are
 *  tiny and even a pasted query is far under this). */
export const MAX_SQL_BYTES = 64 * 1024;

export type QueryResult = {
  columns: string[];
  rows: string[][];
  /** true when we stopped at MAX_OUTPUT_BYTES / the row cap and more data exists. */
  truncated: boolean;
  /** non-null on a MySQL/transport error (already trimmed for display). */
  error: string | null;
  /** ms the query took end-to-end (for the UI). */
  elapsedMs: number;
};

function connectRoot(t: DbNodeTarget): Promise<Client> {
  const conn = new Client();
  return new Promise<Client>((resolve, reject) => {
    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
    conn
      .on("ready", () => { clearTimeout(timer); resolve(conn); })
      .on("error", (e) => { clearTimeout(timer); reject(e); })
      .connect({ host: t.sshHost, port: t.sshPort, username: "root", password: t.rootPassword, readyTimeout: CONNECT_TIMEOUT_MS });
  });
}

/**
 * Run one batch of SQL against `dbName` as the scoped manager user and return the
 * result set (or an error). The SQL is delivered on the mysql process STDIN, so
 * it is opaque to the shell. `--batch --raw` gives us tab-separated output with a
 * header row; NULLs come back as the literal `\N`. Non-SELECT statements produce
 * no rows (columns empty) — the caller reports a generic success.
 */
export async function runScopedSql(t: DbNodeTarget, dbName: string, sql: string): Promise<QueryResult> {
  const started = Date.now();
  // Re-assert the shape of every value that reaches the command line (the caller
  // validates too — belt and braces). The mgr user + db name are OUR generated
  // identifiers; the password is generated [A-Za-z0-9]. None can carry a shell
  // metacharacter, but we verify rather than trust.
  if (!isValidDbIdentifier(dbName)) return errResult(started, "invalid database name");
  if (!isValidDbIdentifier(t.mgrUser)) return errResult(started, "invalid manager user");
  if (!/^[A-Za-z0-9]{1,64}$/.test(t.mgrPassword)) return errResult(started, "invalid manager credential");
  const sqlBuf = Buffer.from(String(sql ?? ""), "utf8");
  if (sqlBuf.length > MAX_SQL_BYTES) return errResult(started, "query too large");

  // `MYSQL_PWD` keeps the password off argv. `timeout` kills a runaway query on
  // the node. `--batch --raw` = tab-separated, header row, no interactive pager.
  // The db name is passed as the default schema; the grant is the real boundary.
  const cmd =
    `MYSQL_PWD='${t.mgrPassword}' timeout ${QUERY_TIMEOUT_S} ` +
    `mysql --user='${t.mgrUser}' --batch --raw --default-character-set=utf8mb4 ` +
    `--connect-timeout=8 '${dbName}'`;

  const conn = await connectRoot(t);
  try {
    return await new Promise<QueryResult>((resolve) => {
      const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } resolve(errResult(started, "query timed out")); }, QUERY_TIMEOUT_MS);
      conn.exec(cmd, (err, stream) => {
        if (err) { clearTimeout(timer); return resolve(errResult(started, err.message)); }
        let out = Buffer.alloc(0);
        let errOut = "";
        let truncated = false;
        stream
          .on("close", (code: number) => {
            clearTimeout(timer);
            if (code && code !== 0) {
              // mysql failed (syntax error, access denied, etc.) — surface stderr.
              const msg = (errOut || out.toString("utf8")).trim() || `mysql exited ${code}`;
              return resolve(errResult(started, msg));
            }
            const parsed = parseBatchTsv(out.toString("utf8"));
            resolve({ columns: parsed.columns, rows: parsed.rows, truncated: truncated || parsed.truncated, error: null, elapsedMs: Date.now() - started });
          })
          .on("data", (d: Buffer) => {
            if (out.length >= MAX_OUTPUT_BYTES) { truncated = true; return; }
            out = out.length + d.length > MAX_OUTPUT_BYTES ? Buffer.concat([out, d.subarray(0, MAX_OUTPUT_BYTES - out.length)]) : Buffer.concat([out, d]);
            if (out.length >= MAX_OUTPUT_BYTES) truncated = true;
          })
          .stderr.on("data", (d: Buffer) => { if (errOut.length < 8000) errOut += d.toString(); });
        // Deliver the SQL over STDIN, then EOF. Never touches the shell.
        stream.end(sqlBuf);
      });
    });
  } finally {
    try { conn.end(); } catch { /* */ }
  }
}

function errResult(started: number, message: string): QueryResult {
  return { columns: [], rows: [], truncated: false, error: sanitizeError(message), elapsedMs: Date.now() - started };
}

/** Trim + de-noise a MySQL/transport error for display (drop the leading
 *  `ERROR 1064 (42000) at line 1:` prefix mysql prints in batch mode). */
export function sanitizeError(message: string): string {
  return String(message ?? "")
    .replace(/^ERROR\s+\d+\s+\([0-9A-Z]+\)\s+at line \d+:\s*/i, "")
    .replace(/^ERROR\s+\d+\s+\([0-9A-Z]+\):\s*/i, "")
    .trim()
    .slice(0, 500) || "Query failed.";
}

/** Rows returned by `mysql --batch` cap. We hard-limit rows too so a caller that
 *  forgets a LIMIT still can't pull an unbounded set into memory/over the wire. */
export const MAX_ROWS = 1000;

/**
 * Parse `mysql --batch --raw` TSV output into columns + rows. In batch mode mysql
 * separates fields with a literal TAB and rows with a newline, and (without
 * --raw's counterpart) escapes tab/newline/backslash inside values; with --raw it
 * does NOT escape, so a value containing a tab/newline is ambiguous — we accept
 * that trade for faithful display of ordinary data and rely on the column count
 * of the header to keep parsing stable for the overwhelmingly common case.
 */
export function parseBatchTsv(text: string): { columns: string[]; rows: string[][]; truncated: boolean } {
  if (!text) return { columns: [], rows: [], truncated: false };
  const lines = text.replace(/\n$/, "").split("\n");
  if (!lines.length || (lines.length === 1 && lines[0] === "")) return { columns: [], rows: [], truncated: false };
  const columns = lines[0].split("\t");
  const rows: string[][] = [];
  let truncated = false;
  for (let i = 1; i < lines.length; i++) {
    if (rows.length >= MAX_ROWS) { truncated = true; break; }
    rows.push(lines[i].split("\t"));
  }
  return { columns, rows, truncated };
}

