  return TABLE_IDENT_RE.test(String(name ?? ""));
}

/** Quote an identifier for embedding between backticks (double internal ``` ` ```). */
export function quoteIdent(name: string): string {
  return "`" + String(name).replace(/`/g, "``") + "`";
}

/** Page size for the row browser (rows per page). */
export const BROWSE_PAGE_SIZE = 50;

export function showTablesSql(): string {
  return "SHOW TABLES;";
}

/** A bounded page of a table's rows. `offset`/`limit` are clamped to integers by
 *  the caller; embedded here as plain numbers (never strings). */
export function browseTableSql(table: string, limit: number, offset: number): string {
  const lim = Math.max(1, Math.min(BROWSE_PAGE_SIZE, Math.floor(limit)));
  const off = Math.max(0, Math.floor(offset));
  return `SELECT * FROM ${quoteIdent(table)} LIMIT ${lim} OFFSET ${off};`;
}

export function countTableSql(table: string): string {
  return `SELECT COUNT(*) AS n FROM ${quoteIdent(table)};`;
}

