"use server";

// Proprietary in-portal DB manager — server actions.
//
// A Nxeon-built replacement for the Adminer file we used to drop into the
// customer's webroot. Everything here runs SERVER-SIDE: the customer never
// receives a DB credential, and every query is executed as the account's SCOPED
// MySQL manager user (see lib/hosting-db.ts + buildDbMgrGrantSql), which MySQL
// confines to this account's own `<username>_*` databases and nothing else.
//
// AUTH: every action requires the authenticated OWNER of the account (or an
// ADMIN). Actions that RUN SQL or reveal row data additionally call
// assertNotImpersonating — an admin impersonating a customer must not read or
// mutate that customer's live data (same discipline as revealHostingSftpPassword
// / createHostingDatabase). Read-only "which databases exist" listing (from OUR
// portal tables, not the node) is owner-or-admin without that extra bar.

import { randomBytes } from "node:crypto";
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { SANDBOX } from "./sandbox";
import { encryptSecret } from "./crypto-box";
import { checkRateLimit } from "./rate-limit";
import { isValidUnixUsername, isValidDbIdentifier, dbMgrUserFor } from "./hosting";
import {
  dbTargetFor,
  runScopedSql,
  showTablesSql,
  browseTableSql,
  countTableSql,
  isPlausibleTableName,
  MAX_SQL_BYTES,
  BROWSE_PAGE_SIZE,
  type QueryResult,
} from "./hosting-db";

export type DbMgrStatus = { ready: boolean; provisioning: boolean; enabled: boolean };
export type DbMgrDatabase = { name: string; status: string };
export type DbMgrResult = {
  columns: string[];
  rows: string[][];
  truncated: boolean;
  error: string | null;
  elapsedMs: number;
  /** For non-SELECT statements (empty result set) — a friendly "OK" note. */
  ok?: boolean;
};

/** Owner-or-admin account load with the node relation + manager fields. */
async function loadOwned(accountId: string) {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({
    where: { id: accountId },
    include: { node: { select: { sshHost: true, sshPort: true, rootPasswordEnc: true } } },
  });
  if (!a) return { error: "Account not found." as const };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
  return { user, a };
}

/** Confirm a target db name actually belongs to THIS account (defence in depth
 *  on top of the MySQL grant). Returns the matched row or null. */
async function assertOwnedDatabase(accountId: string, dbName: string) {
  if (!isValidDbIdentifier(dbName)) return null;
  return db.hostingDatabase.findFirst({ where: { accountId, name: dbName } });
}

/** A short, alphanumeric (shell/SQL-safe) secret. */
function newSecret(len = 24): string {
  return randomBytes(48).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, len);
}

/**
 * Make sure the account has a provisioned DB-manager user. Idempotent:
 *   - already ready → { ready:true }
 *   - has creds but no ACTIVE user yet (or first call) → generate creds if
 *     missing, queue ENSURE_DBMGR, report { provisioning:true }
 * Owner-or-admin + not-impersonating (this mints a live DB credential on the box).
 * SANDBOX: mark ready immediately (no real node).
 */
export async function ensureDbManager(accountId: string): Promise<DbMgrStatus & { error?: string }> {
  const ctx = await loadOwned(accountId);
  if ("error" in ctx) return { ready: false, provisioning: false, enabled: false, error: ctx.error };
  await assertNotImpersonating();
  const { a } = ctx;
  if (!isValidUnixUsername(a.username)) return { ready: false, provisioning: false, enabled: false, error: "Account not ready." };

  if (SANDBOX) {
    if (!a.dbMgrReady) {
      await db.hostingAccount.update({
        where: { id: a.id },
        data: { dbMgrUser: dbMgrUserFor(a.username), dbMgrPassEnc: encryptSecret(newSecret()), dbMgrReady: true },
      });
    }
    return { ready: true, provisioning: false, enabled: true };
  }

  if (a.dbMgrReady && a.dbMgrUser && a.dbMgrPassEnc) return { ready: true, provisioning: false, enabled: true };

  // Generate + persist the manager credential once (encrypted at rest); the
  // worker applies it on the node. Keep the same password across re-queues so the
  // stored cred always matches what the node was told.
  if (!a.dbMgrUser || !a.dbMgrPassEnc) {
    await db.hostingAccount.update({
      where: { id: a.id },
      data: { dbMgrUser: dbMgrUserFor(a.username), dbMgrPassEnc: encryptSecret(newSecret()), dbMgrReady: false },
    });
  }
  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "ENSURE_DBMGR", status: { in: ["PENDING", "RUNNING"] } } });
  if (!inFlight) await db.hostingTask.create({ data: { accountId, kind: "ENSURE_DBMGR" } });
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ready: false, provisioning: true, enabled: true };
}

export async function dbmgrStatus(accountId: string): Promise<DbMgrStatus & { error?: string }> {
  const ctx = await loadOwned(accountId);
  if ("error" in ctx) return { ready: false, provisioning: false, enabled: false, error: ctx.error };
  const { a } = ctx;
  if (SANDBOX) return { ready: !!a.dbMgrReady, provisioning: false, enabled: true };
  const provisioning = !a.dbMgrReady && !!(await db.hostingTask.findFirst({ where: { accountId, kind: "ENSURE_DBMGR", status: { in: ["PENDING", "RUNNING"] } } }));
  return { ready: !!a.dbMgrReady, provisioning, enabled: true };
}

/** The account's databases — read straight from OUR portal tables (never the
 *  node), so this leaks nothing and needs no MySQL round-trip. Owner-or-admin. */
export async function dbmgrListDatabases(accountId: string): Promise<{ error?: string; databases?: DbMgrDatabase[] }> {
  const ctx = await loadOwned(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const rows = await db.hostingDatabase.findMany({ where: { accountId, status: { in: ["ACTIVE", "PENDING"] } }, orderBy: { createdAt: "asc" } });
  return { databases: rows.map((r) => ({ name: r.name, status: r.status })) };
}

/** Rate-limit the SQL surface per user (a customer-exposed exec path). */
function rlOk(userId: string, accountId: string): boolean {
  return checkRateLimit(`dbmgr:${userId}:${accountId}`, { max: 60, windowMs: 60_000 }).ok;
}

const SANDBOX_TABLES = ["customers", "orders", "products"];
function sandboxResult(sql: string): DbMgrResult {
  const s = sql.trim().toLowerCase();
  if (s.startsWith("show tables")) {
    return { columns: ["Tables_in_demo"], rows: SANDBOX_TABLES.map((t) => [t]), truncated: false, error: null, elapsedMs: 3 };
  }
  if (s.startsWith("select count(")) {
    return { columns: ["n"], rows: [["3"]], truncated: false, error: null, elapsedMs: 2 };
  }
  if (s.startsWith("select")) {
    return {
      columns: ["id", "name", "created_at"],
      rows: [["1", "Ada Lovelace", "2026-01-02 10:00:00"], ["2", "Grace Hopper", "2026-01-03 11:30:00"], ["3", "Katherine Johnson", "2026-01-04 09:15:00"]],
      truncated: false, error: null, elapsedMs: 4,
    };
  }
  return { columns: [], rows: [], truncated: false, error: null, elapsedMs: 2, ok: true };
}

/** List a database's tables (SHOW TABLES as the scoped user). Owner-or-admin +
 *  not-impersonating (it reaches the customer's live data). */
export async function dbmgrListTables(accountId: string, dbName: string): Promise<{ error?: string; tables?: string[] }> {
  const ctx = await loadOwned(accountId);
  if ("error" in ctx) return { error: ctx.error };
  await assertNotImpersonating();
  const { user } = ctx;
  if (!(await assertOwnedDatabase(accountId, dbName))) return { error: "Unknown database." };
  if (!rlOk(user.id, accountId)) return { error: "Too many requests — slow down a moment." };
  if (SANDBOX) return { tables: SANDBOX_TABLES };
  const target = dbTargetFor(ctx.a);
  if (!target) return { error: "The database manager is still being prepared." };
  const res = await runScopedSql(target, dbName, showTablesSql());
  if (res.error) return { error: res.error };
  return { tables: res.rows.map((r) => r[0]).filter(Boolean) };
}

/** Browse a page of a table's rows. Validates the table by MEMBERSHIP against the
 *  db's real table list (so a user can't name a table they can't see), then runs
 *  a bounded SELECT + a COUNT. Owner-or-admin + not-impersonating. */
export async function dbmgrBrowseTable(
  accountId: string,
  dbName: string,
  table: string,
  page: number,
): Promise<{ error?: string; columns?: string[]; rows?: string[][]; total?: number | null; page?: number; pageSize?: number; truncated?: boolean }> {
  const ctx = await loadOwned(accountId);
  if ("error" in ctx) return { error: ctx.error };
  await assertNotImpersonating();
  const { user } = ctx;
  if (!(await assertOwnedDatabase(accountId, dbName))) return { error: "Unknown database." };
  if (!isPlausibleTableName(table)) return { error: "Invalid table name." };
  if (!rlOk(user.id, accountId)) return { error: "Too many requests — slow down a moment." };
  const p = Math.max(0, Math.floor(Number(page) || 0));

  if (SANDBOX) {
    const demo = sandboxResult("select");
    return { columns: demo.columns, rows: demo.rows, total: demo.rows.length, page: p, pageSize: BROWSE_PAGE_SIZE, truncated: false };
  }
  const target = dbTargetFor(ctx.a);
  if (!target) return { error: "The database manager is still being prepared." };

  // Membership check: the table MUST be one the scoped user can actually see.
  const listed = await runScopedSql(target, dbName, showTablesSql());
  if (listed.error) return { error: listed.error };
  const tables = listed.rows.map((r) => r[0]);
  if (!tables.includes(table)) return { error: "Unknown table." };

  const res = await runScopedSql(target, dbName, browseTableSql(table, BROWSE_PAGE_SIZE, p * BROWSE_PAGE_SIZE));
  if (res.error) return { error: res.error };
  const countRes = await runScopedSql(target, dbName, countTableSql(table));
  const total = countRes.error ? null : Number(countRes.rows[0]?.[0] ?? "0");
  return { columns: res.columns, rows: res.rows, total: Number.isFinite(total as number) ? (total as number) : null, page: p, pageSize: BROWSE_PAGE_SIZE, truncated: res.truncated };
}

/**
 * Run arbitrary SQL scoped to one of the account's databases. The SQL travels to
 * the node's `mysql` client over STDIN (never a shell), executed as the scoped
 * manager user — MySQL's grant is the hard isolation boundary. Owner-or-admin +
 * not-impersonating + rate-limited.
 */
export async function dbmgrRunSql(accountId: string, dbName: string, sql: string): Promise<DbMgrResult & { error?: string }> {
  const empty: DbMgrResult = { columns: [], rows: [], truncated: false, error: null, elapsedMs: 0 };
  const ctx = await loadOwned(accountId);
  if ("error" in ctx) return { ...empty, error: ctx.error };
  await assertNotImpersonating();
  const { user } = ctx;
  if (!(await assertOwnedDatabase(accountId, dbName))) return { ...empty, error: "Unknown database." };
  const text = String(sql ?? "").trim();
  if (!text) return { ...empty, error: "Enter a SQL statement." };
  if (Buffer.byteLength(text, "utf8") > MAX_SQL_BYTES) return { ...empty, error: "That query is too large." };
  if (!rlOk(user.id, accountId)) return { ...empty, error: "Too many requests — slow down a moment." };

  if (SANDBOX) return sandboxResult(text);
  const target = dbTargetFor(ctx.a);
  if (!target) return { ...empty, error: "The database manager is still being prepared." };
  const res: QueryResult = await runScopedSql(target, dbName, text);
  if (res.error) return { ...res, error: res.error };
  return { ...res, ok: res.columns.length === 0 };
}

