/**
 * Provision (or repair) the account-level scoped MySQL user for the PROPRIETARY
 * in-portal DB manager. Creates `<username>_mgr`@'localhost' and grants it on
 * `<username>\_%`.* ONLY — every one of THIS account's databases and nothing else
 * (see buildDbMgrGrantSql for the escaped-glob isolation proof). The password was
 * generated + stored encrypted by ensureDbManager; we decrypt it here to apply
 * it. Idempotent (CREATE USER IF NOT EXISTS + ALTER USER re-asserts the password,
 * so a repair run realigns the box with the stored cred). Flips dbMgrReady=true
 * so the portal can start executing queries as this user.
 *
 * SECURITY: the grant is db-scoped, so `ALL PRIVILEGES` confers NO global
 * FILE/PROCESS/SUPER — this user can never read node files or reach a peer's
 * databases or the `mysql`/system schemas. The SQL is built from validated
 * identifiers and a `[A-Za-z0-9]` password, shell-escaped for `mysql -e` exactly
 * like the per-database create.
 */
async function taskEnsureDbMgr(conn: Client, a: { id: string; username: string; dbMgrUser: string | null; dbMgrPassEnc: string | null }): Promise<void> {
  const u = a.username;
  if (!isValidUnixUsername(u)) throw new Error("unsafe account username");
  const mgrUser = a.dbMgrUser || dbMgrUserFor(u);
  const pass = a.dbMgrPassEnc ? decryptSecret(a.dbMgrPassEnc) : "";
  if (!/^[a-z0-9_]{1,32}$/.test(mgrUser) || !pass || !/^[A-Za-z0-9]{1,64}$/.test(pass)) {
    throw new Error("invalid db-manager credential");
  }
  const sql = sqlForMysqlExec(buildDbMgrGrantSql(u, mgrUser, pass));
  await run(conn, "ensure db-manager user", `mysql -e "${sql}"`);
  await db.hostingAccount.update({ where: { id: a.id }, data: { dbMgrUser: mgrUser, dbMgrReady: true } });
}

else if (task.kind === "INSTALL_DBTOOL") result = await taskInstallDbTool(conn, a, task.payload);
else if (task.kind === "ENSURE_DBMGR") await taskEnsureDbMgr(conn, a);
else if (task.kind === "APPLY_PLAN_LIMITS") await taskApplyPlanLimits(conn, a);

