"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  ensureDbManager,
  dbmgrStatus,
  dbmgrListDatabases,
  dbmgrListTables,
  dbmgrBrowseTable,
  dbmgrRunSql,
  type DbMgrDatabase,
} from "@/lib/actions-hosting-db";

/**
 * Nxeon DB Studio — the PROPRIETARY, in-portal database manager (replaces the
 * third-party Adminer file we used to drop into the webroot). All SQL runs
 * server-side as the account's scoped MySQL user, so it can only ever touch this
 * account's own databases. Nothing here ever holds a DB credential.
 */
export function DbManager({ accountId }: { accountId: string }) {
  const [status, setStatus] = useState<"loading" | "provisioning" | "ready" | "error">("loading");
  const [statusMsg, setStatusMsg] = useState("");
  const [databases, setDatabases] = useState<DbMgrDatabase[]>([]);
  const [activeDb, setActiveDb] = useState<string>("");
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Kick provisioning + load the account's databases on mount.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const [ens, list] = await Promise.all([ensureDbManager(accountId), dbmgrListDatabases(accountId)]);
      if (cancelled) return;
      if (list.databases) {
        setDatabases(list.databases);
        const firstActive = list.databases.find((d) => d.status === "ACTIVE") ?? list.databases[0];
        if (firstActive) setActiveDb(firstActive.name);
      }
      if (ens.error) { setStatus("error"); setStatusMsg(ens.error); return; }
      if (ens.ready) { setStatus("ready"); return; }
      setStatus("provisioning");
    })();
    return () => { cancelled = true; };
  }, [accountId]);

  // Poll until the manager user is provisioned on the node.
  useEffect(() => {
    if (status !== "provisioning") return;
    let tries = 0;
    pollRef.current = setInterval(async () => {
      tries++;
      const s = await dbmgrStatus(accountId);
      if (s.ready) { setStatus("ready"); if (pollRef.current) clearInterval(pollRef.current); return; }
      if (tries >= 20) { setStatus("error"); setStatusMsg("The database manager is taking longer than expected to set up. Try again shortly."); if (pollRef.current) clearInterval(pollRef.current); }
    }, 3000);
    return () => { if (pollRef.current) clearInterval(pollRef.current); };
  }, [status, accountId]);

  if (databases.length === 0 && status !== "loading") {
    return (
      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-4 py-6 text-center">
        <p className="text-sm text-slate-300">No databases yet</p>
        <p className="mt-1 text-xs text-slate-500">Create a database below, then open Nxeon DB Studio to browse and query it.</p>
      </div>
    );
  }

  return (
    <div className="rounded-xl border border-white/[0.06] bg-navy-900/50 p-4">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-2">
        <div className="flex items-center gap-2">
          <span className="flex h-6 w-6 items-center justify-center rounded-md bg-gradient-to-br from-accent-blue to-brand-500 text-[11px] font-bold text-white">N</span>
          <h3 className="text-sm font-semibold text-slate-200">Nxeon DB Studio</h3>
          <span className="rounded bg-white/[0.06] px-1.5 py-0.5 text-[10px] uppercase tracking-wide text-slate-400">Beta</span>
        </div>
        {databases.length > 0 && (
          <select
            value={activeDb}
            onChange={(e) => setActiveDb(e.target.value)}
            className="input max-w-[16rem] text-xs"
          >
            {databases.map((d) => (
              <option key={d.name} value={d.name} disabled={d.status !== "ACTIVE"}>
                {d.name}{d.status !== "ACTIVE" ? ` (${d.status.toLowerCase()})` : ""}
              </option>
            ))}
          </select>
        )}
      </div>

      {status === "loading" && <p className="text-xs text-slate-500">Loading…</p>}
      {status === "provisioning" && (
        <p className="text-xs text-amber-300">Preparing your secure database connection… this only happens once.</p>
      )}
      {status === "error" && <p className="text-xs text-amber-300">{statusMsg}</p>}

      {status === "ready" && activeDb && <Workbench accountId={accountId} dbName={activeDb} key={activeDb} />}
    </div>
  );
}

/* ------------------------------------------------------------- Workbench --- */

function Workbench({ accountId, dbName }: { accountId: string; dbName: string }) {
  const [tables, setTables] = useState<string[]>([]);
  const [tablesErr, setTablesErr] = useState("");
  const [activeTable, setActiveTable] = useState<string>("");
  const [view, setView] = useState<"browse" | "sql">("browse");

  const loadTables = useCallback(async () => {
    setTablesErr("");
    const res = await dbmgrListTables(accountId, dbName);
    if (res.error) { setTablesErr(res.error); setTables([]); return; }
    setTables(res.tables ?? []);
  }, [accountId, dbName]);

  useEffect(() => { loadTables(); }, [loadTables]);

  return (
    <div className="grid gap-4 md:grid-cols-[13rem_1fr]">
      {/* Tables sidebar */}
      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-2">
        <div className="mb-2 flex items-center justify-between px-1">
          <span className="text-[11px] font-medium uppercase tracking-wide text-slate-500">Tables</span>
          <button type="button" className="text-[11px] text-brand-300 hover:underline" onClick={loadTables}>refresh</button>
        </div>
        {tablesErr && <p className="px-1 text-[11px] text-amber-300">{tablesErr}</p>}
        {!tablesErr && tables.length === 0 && <p className="px-1 text-[11px] text-slate-500">No tables in this database.</p>}
        <ul className="max-h-72 space-y-0.5 overflow-y-auto">
          {tables.map((t) => (
            <li key={t}>
              <button
                type="button"
                onClick={() => { setActiveTable(t); setView("browse"); }}
                className={`w-full truncate rounded px-2 py-1 text-left font-mono text-xs ${activeTable === t && view === "browse" ? "bg-brand-500/20 text-brand-200" : "text-slate-300 hover:bg-white/[0.04]"}`}
                title={t}
              >
                {t}
              </button>
            </li>
          ))}
        </ul>
        <button
          type="button"
          onClick={() => setView("sql")}
          className={`mt-2 w-full rounded px-2 py-1 text-left text-xs ${view === "sql" ? "bg-brand-500/20 text-brand-200" : "text-slate-300 hover:bg-white/[0.04]"}`}
        >
          ✎ SQL query
        </button>
      </div>

      {/* Main pane */}
      <div className="min-w-0">
        {view === "browse" && activeTable && <BrowseTable accountId={accountId} dbName={dbName} table={activeTable} />}
        {view === "browse" && !activeTable && <p className="text-xs text-slate-500">Pick a table on the left to browse its rows, or open the SQL query editor.</p>}
        {view === "sql" && <SqlEditor accountId={accountId} dbName={dbName} onChanged={loadTables} />}
      </div>
    </div>
  );
}

/* ------------------------------------------------------------ BrowseTable --- */

function BrowseTable({ accountId, dbName, table }: { accountId: string; dbName: string; table: string }) {
  const [page, setPage] = useState(0);
  const [data, setData] = useState<{ columns: string[]; rows: string[][]; total: number | null; pageSize: number; truncated: boolean } | null>(null);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);

  useEffect(() => { setPage(0); }, [table]);

  useEffect(() => {
    let cancelled = false;
    setBusy(true); setErr("");
    dbmgrBrowseTable(accountId, dbName, table, page).then((res) => {
      if (cancelled) return;
      setBusy(false);
      if (res.error) { setErr(res.error); setData(null); return; }
      setData({ columns: res.columns ?? [], rows: res.rows ?? [], total: res.total ?? null, pageSize: res.pageSize ?? 50, truncated: !!res.truncated });
    });
    return () => { cancelled = true; };
  }, [accountId, dbName, table, page]);

  const total = data?.total ?? null;
  const pageSize = data?.pageSize ?? 50;
  const maxPage = total != null ? Math.max(0, Math.ceil(total / pageSize) - 1) : (data && data.rows.length === pageSize ? page + 1 : page);

  return (
    <div>
      <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
        <p className="font-mono text-sm text-slate-200">{table}{total != null && <span className="ml-2 text-xs text-slate-500">{total.toLocaleString()} rows</span>}</p>
        <div className="flex items-center gap-1 text-xs">
          <button className="btn-secondary px-2 py-0.5 text-xs disabled:opacity-40" disabled={busy || page === 0} onClick={() => setPage((p) => Math.max(0, p - 1))}>‹ Prev</button>
          <span className="px-1 text-slate-500">page {page + 1}</span>
          <button className="btn-secondary px-2 py-0.5 text-xs disabled:opacity-40" disabled={busy || page >= maxPage} onClick={() => setPage((p) => p + 1)}>Next ›</button>
        </div>
      </div>
      {err && <p className="text-xs text-amber-300">{err}</p>}
      {data && <ResultGrid columns={data.columns} rows={data.rows} truncated={data.truncated} />}
    </div>
  );
}

/* ------------------------------------------------------------- SqlEditor --- */

function SqlEditor({ accountId, dbName, onChanged }: { accountId: string; dbName: string; onChanged: () => void }) {
  const [sql, setSql] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [note, setNote] = useState("");
  const [result, setResult] = useState<{ columns: string[]; rows: string[][]; truncated: boolean } | null>(null);

  async function run() {
    if (!sql.trim()) return;
    setBusy(true); setErr(""); setNote(""); setResult(null);
    const res = await dbmgrRunSql(accountId, dbName, sql);
    setBusy(false);
    if (res.error) { setErr(res.error); return; }
    if (res.columns.length === 0) {
      setNote(`Statement executed in ${res.elapsedMs} ms.`);
      onChanged(); // a DDL/DML may have changed the table list
      return;
    }
    setResult({ columns: res.columns, rows: res.rows, truncated: res.truncated });
    setNote(`${res.rows.length} row${res.rows.length === 1 ? "" : "s"} · ${res.elapsedMs} ms`);
  }

  return (
    <div>
      <p className="mb-1 text-[11px] text-slate-500">
        Running against <span className="font-mono text-slate-300">{dbName}</span>. Queries run as your database user — they can only ever touch your own databases.
      </p>
      <textarea
        className="input h-28 w-full font-mono text-xs"
        placeholder="SELECT * FROM your_table LIMIT 20;"
        value={sql}
        onChange={(e) => setSql(e.target.value)}
        onKeyDown={(e) => { if ((e.metaKey || e.ctrlKey) && e.key === "Enter") run(); }}
      />
      <div className="mt-2 flex items-center gap-2">
        <button className="btn-secondary text-xs" disabled={busy || !sql.trim()} onClick={run}>{busy ? "Running…" : "Run"}</button>
        <span className="text-[11px] text-slate-500">⌘/Ctrl + Enter</span>
        {note && <span className="text-[11px] text-slate-400">{note}</span>}
      </div>
      {err && <p className="mt-2 whitespace-pre-wrap rounded border border-amber-500/30 bg-amber-500/10 px-2 py-1.5 font-mono text-[11px] text-amber-200">{err}</p>}
      {result && <div className="mt-3"><ResultGrid columns={result.columns} rows={result.rows} truncated={result.truncated} /></div>}
    </div>
  );
}

/* ------------------------------------------------------------- ResultGrid --- */

function ResultGrid({ columns, rows, truncated }: { columns: string[]; rows: string[][]; truncated: boolean }) {
  if (columns.length === 0) return <p className="text-xs text-slate-500">No columns.</p>;
  return (
    <div>
      <div className="overflow-x-auto rounded-lg border border-white/[0.06]">
        <table className="min-w-full text-left text-xs">
          <thead className="bg-white/[0.03]">
            <tr>
              {columns.map((c, i) => (
                <th key={i} className="whitespace-nowrap border-b border-white/[0.06] px-3 py-1.5 font-medium text-slate-300">{c}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.length === 0 && (
              <tr><td colSpan={columns.length} className="px-3 py-3 text-center text-slate-500">No rows.</td></tr>
            )}
            {rows.map((r, ri) => (
              <tr key={ri} className="odd:bg-white/[0.01]">
                {columns.map((_, ci) => (
                  <td key={ci} className="max-w-xs truncate border-b border-white/[0.04] px-3 py-1 font-mono text-slate-400" title={cell(r[ci])}>{cell(r[ci])}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {truncated && <p className="mt-1 text-[11px] text-amber-300">Results truncated — refine your query with a LIMIT or WHERE clause to see more.</p>}
    </div>
  );
}

/** `mysql --batch` renders SQL NULL as the literal `\N`; show it as a muted NULL. */
function cell(v: string | undefined): string {
  if (v === undefined) return "";
  if (v === "\\N") return "NULL";
  return v;
}

