/** Sentinel a NULL cell resolves to (chosen so it can't collide with a real
 *  escaped value; the UI renders it as a muted "NULL"). */
export const NULL_CELL = "�NULL�";

/** Unescape one `mysql --batch` field: `\N` (whole field) → NULL sentinel, and
 *  the in-value escapes `\t` `\n` `\0` `\\` back to their literals. */
function unescapeField(f: string): string {
  if (f === "\\N") return NULL_CELL;
  let out = "";
  for (let i = 0; i < f.length; i++) {
    if (f[i] === "\\" && i + 1 < f.length) {
      const n = f[++i];
      out += n === "t" ? "\t" : n === "n" ? "\n" : n === "0" ? "\0" : n === "\\" ? "\\" : n;
    } else {
      out += f[i];
    }
  }
  return out;
}

/**
 * Parse `mysql --batch` TSV output into columns + rows. Fields are TAB-separated,
 * rows newline-separated; mysql escapes any tab/newline/backslash INSIDE a value,
 * so splitting on the raw delimiters is unambiguous, then we unescape each field.
 */
export function parseBatchTsv(text: string): { columns: string[]; rows: string[][]; truncated: boolean } {
  if (!text) return { columns: [], rows: [], truncated: false };
  const lines = text.replace(/\n$/, "").split("\n");
  if (!lines.length || (lines.length === 1 && lines[0] === "")) return { columns: [], rows: [], truncated: false };
  const columns = lines[0].split("\t").map(unescapeField);
  const rows: string[][] = [];
  let truncated = false;
  for (let i = 1; i < lines.length; i++) {
    if (rows.length >= MAX_ROWS) { truncated = true; break; }
    rows.push(lines[i].split("\t").map(unescapeField));
  }
  return { columns, rows, truncated };
}

